python
def undoDrawerEvenKeyCensus(readings, k):
    a=readings
    out=[]
    for x in a:
        if x>=0: out.append(x)
        else:
            for _ in range(min(-x,len(out))): out.pop()
    return sum(x%2==0 for x in out)


java
class Solution {
  public int undoDrawerEvenKeyCensus(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){if(x>=0)out.add(x);else for(int i=0;i<-x&&!out.isEmpty();i++)out.remove(out.size()-1);}}
    int answer=0;for(int x:out)if(x%2==0)answer++;return answer;
  }
}
